"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { Paper } from "@/components/ui/paper"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { alertRecipe, type AlertTone } from "@/lib/ink/recipes/alert-ink"
import { cn } from "@/lib/utils"

const alertVariants = cva(
  "relative isolate grid w-full grid-cols-[0_1fr] items-start gap-y-0.5 px-4 py-3 text-sm compact:py-2.5 calm:px-3 calm:py-2 has-[>svg:not(.absolute)]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg:not(.absolute)]:gap-x-3 [&>svg:not(.absolute)]:size-4 [&>svg:not(.absolute)]:translate-y-0.5 [&>svg:not(.absolute)]:text-current [&:not(:has(>svg:not(.absolute)))>svg_[data-part=icon-mark]]:hidden",
  {
    variants: {
      variant: {
        default: "text-card-foreground",
        destructive: "text-destructive *:data-[slot=alert-description]:text-destructive [&>svg:not(.absolute)]:text-current",
        info: "text-card-foreground [&>svg:not(.absolute)]:text-ink-you",
        success: "text-card-foreground [&>svg:not(.absolute)]:text-green",
        warning: "text-card-foreground",
        note: "px-5 py-4 text-ink *:data-[slot=alert-description]:text-ink-soft",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function Alert({
  className,
  variant,
  seed,
  ref,
  children,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof alertVariants> & {
    seed?: string | number
  }) {
  const tone: AlertTone = variant ?? "default"
  const { hostRef, hostProps, node } = useInk({ recipe: alertRecipe, params: { tone }, kind: "alert", seed, still: true })
  const merged = useMergedRef<HTMLDivElement>(hostRef, ref)

  if (tone === "note") {
    return (
      <Paper
        data-slot="alert"
        role="alert"
        stock="sticky-yellow"
        tape="corner"
        seed={seed}
        ref={ref as React.Ref<HTMLElement> | undefined}
        className={cn(alertVariants({ variant }), className)}
        {...props}
      >
        {children}
      </Paper>
    )
  }

  return (
    <div
      data-slot="alert"
      data-variant={tone}
      role="alert"
      ref={merged}
      {...hostProps}
      className={cn(alertVariants({ variant }), className)}
      {...props}
    >
      {node}
      {children}
    </div>
  )
}

function AlertTitle({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="alert-title" className={cn("col-start-2 line-clamp-1 min-h-4 font-bold", className)} {...props} />
}

function AlertDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn("col-start-2 grid justify-items-start gap-1 text-sm text-muted-foreground [&_p]:leading-relaxed", className)}
      {...props}
    />
  )
}

export { Alert, AlertTitle, AlertDescription }

import { bandFill, blobFill, wash } from '@/lib/ink/fills'
import { ellipsePoly, roundRectPoly } from '@/lib/ink/geom'
import { defineRecipe } from '@/lib/ink/recipes'
import { box, line, loop } from '@/lib/ink/shapes'
import type { PaintKey } from '@/lib/ink/paint'
import type { PenName } from '@/lib/ink/types'

export type AlertTone = 'default' | 'destructive' | 'info' | 'success' | 'warning' | 'note'

export interface AlertParams {
  tone: AlertTone
}

const PEN: Record<AlertTone, PenName> = { default: 'ink', destructive: 'redfelt', info: 'blue', success: 'greenfelt', warning: 'ink', note: 'ink' }
const HAIR: Record<AlertTone, PenName> = { default: 'pencil.fine', destructive: 'red.fine', info: 'bluepencil.fine', success: 'green.fine', warning: 'pencil.fine', note: 'pencil.fine' }

const MARK: Record<AlertTone, PaintKey> = { default: 'pencil-mark', destructive: 'red', info: 'sky', success: 'grass', warning: 'tangerine', note: 'pencil-mark' }

export const alertRecipe = defineRecipe<AlertParams>({
  id: 'alert',
  kind: 'alert',
  layers: ['rest'],
  pad: 12,
  draw(ink, { w, h }, { tone }, ctx) {
    if (tone === 'note') return
    const r = 3
    const body = roundRectPoly(1.5, 1.5, w - 3, h - 3, r)
    const calm = ctx.calm
    const rtl = ctx.dir === 'rtl'
    const X = (x: number): number => (rtl ? w - x : x)
    const wide = w > 360
    ink.layer('rest', () => {
      ink.poly('under', body, 'slip', 0.94)
      if (tone === 'warning') ink.part('fill', () => bandFill(ink, body, 'hi', { alpha: calm ? 0.4 : 0.6, passes: 1, ends: 'flag' }))
      if (calm) {
        if (tone !== 'default' && tone !== 'warning') line(ink, X(6.5), 4, X(6.5), h - 4, { pen: HAIR[tone], single: true, opts: { alpha: 0.9 } })
      } else if (tone === 'destructive') {
        wash(ink, body, 'red', { alpha: 0.04 })
        ink.part('fill', () => bandFill(ink, roundRectPoly(rtl ? w - 11 : 3, 3.5, 8, h - 7, 2), 'red', { alpha: 0.9, passes: 1, ends: 'square', W: 5 }))
      } else if (tone === 'info') {
        line(ink, X(5.2), 5, X(5.6), h - 5, { pen: 'bluepencil', single: true })
        line(ink, X(10), 5.5, X(10.4), h - 6, { pen: 'bluepencil', single: true, opts: { alpha: 0.75 } })
      } else if (tone === 'success') {
        ink.part('fill', () => bandFill(ink, roundRectPoly(rtl ? w - 11 : 3, 3.5, 8, h - 7, 2), 'grass', { alpha: 0.7, passes: 1, ends: 'square', W: 5 }))
      }
      if (!calm) {
        const px = 16
        const py = ctx.density === 'compact' ? 10 : 12
        const cx = X(px + 8), cy = py + 10
        ink.part('icon-mark', () => {
          const off = blobFill(ink, ellipsePoly(cx, cy, 11.5, 11.5, 20), MARK[tone], { alpha: tone === 'default' ? 0.3 : 0.32, mis: 1.6 })
          loop(ink, cx, cy, 12.5, 12.5, { pen: tone === 'default' ? 'pencil.fine' : HAIR[tone], turns: 1.08 })
          return off
        })
      }
      if (calm) box(ink, 0, 0, w, h, { pen: HAIR[tone], corner: r, style: 'loop', stubs: false, ghost: false })
      else box(ink, 0, 0, w, h, { pen: PEN[tone], corner: r, opts: wide ? { simple: true } : undefined })
    })
  },
})

